#!/usr/bin/env bash
# Generate the Python reference's goldens for one sweep-gate case.
#
# The goldens are the ONLY producer of parity evidence: a golden is never written
# by Go. Every captured frame carries the marker line
#
#   # generated by sweep-gate.py@<sha8>
#
# where <sha8> is the first 8 hex characters of the reference script's sha256, so
# a file produced by the Go port cannot pass as a reference capture.
#
# Usage:
#   testdata/sweepgate/generate.sh [case-name] [--vault DIR] [--subject NAME]
#
# The checked-in default is case `parity-topic` against
# `testdata/sweepgate/vault`. The script is re-runnable: the state directories are
# throwaway copies, so `changed` is true on every run and the marker always reads
# `change`.
set -eu

REPO_ROOT=$(cd "$(dirname "$0")/../.." && pwd)
REFERENCE_DIR="$REPO_ROOT/testdata/sweepgate/reference"
REFERENCE="$REFERENCE_DIR/sweep-gate.py"
BOX_TABLE="$REFERENCE_DIR/box-table.py"
INPUTS="$REPO_ROOT/testdata/sweepgate/inputs"

CASE="parity-topic"
VAULT="$REPO_ROOT/testdata/sweepgate/vault"
SUBJECT=""

while [ $# -gt 0 ]; do
    case "$1" in
        --vault)
            VAULT=$2
            shift 2
            ;;
        --subject)
            SUBJECT=$2
            shift 2
            ;;
        -*)
            echo "unknown option: $1" >&2
            exit 2
            ;;
        *)
            CASE=$1
            shift
            ;;
    esac
done

if [ -z "$SUBJECT" ]; then
    # `parity-topic` -> `Parity Topic`.
    SUBJECT=$(printf '%s' "$CASE" | tr '-' ' ' | awk '{for(i=1;i<=NF;i++) $i=toupper(substr($i,1,1)) substr($i,2)} 1')
fi

if [ ! -f "$REFERENCE" ]; then
    echo "missing reference: $REFERENCE" >&2
    exit 1
fi
if [ ! -f "$BOX_TABLE" ]; then
    echo "missing reference: $BOX_TABLE" >&2
    exit 1
fi
if [ ! -d "$VAULT" ]; then
    echo "missing vault: $VAULT" >&2
    exit 1
fi

SHA8=$(sha256sum "$REFERENCE" | cut -c1-8)
MARKER="# generated by sweep-gate.py@$SHA8"

# A fixed throwaway base keeps the captured `park:` stderr line stable across
# runs. Both state directories are emptied first, so a re-run is a first run.
BASE="${TMPDIR:-/tmp}/sweepgate-generate"
rm -rf "$BASE"
mkdir -p "$BASE/render-state" "$BASE/tick-state" "$BASE/settled"

# The reference resolves BOX_TABLE under `~/.claude/plugins/...`, a marketplace
# path that does not exist in the container. Stage HOME with a symlink to the
# vendored copy. Resolve the target to an absolute path first so the link
# survives the `cd`.
TMPHOME="$BASE/home"
mkdir -p "$TMPHOME/.claude/plugins/marketplaces/claude-supervisor/scripts"
BOX_TABLE_ABS=$(cd "$(dirname "$BOX_TABLE")" && pwd)/$(basename "$BOX_TABLE")
ln -s "$BOX_TABLE_ABS" \
    "$TMPHOME/.claude/plugins/marketplaces/claude-supervisor/scripts/box-table.py"

export HOME="$TMPHOME"
export BOX_TABLE_NO_LINKS=1
export SWEEP_GATE_SETTLED_DIR="$BASE/settled"
export SWEEP_GATE_FEED_DIR="$INPUTS/feed"
export SWEEP_GATE_HOLDS="$INPUTS/session-holds.json"
export SWEEP_GATE_PREDISPATCH_DIR="$INPUTS/manager-predispatch"
export SWEEP_GATE_WORKER_MANAGER_DIR="$BASE/worker-manager"
# An unreachable store makes the feed reader fall through to the event log, which
# is the source the fixture carries.
export SWEEP_GATE_STORE_URL="http://127.0.0.1:1"

OUT_DIR="$REPO_ROOT/testdata/sweepgate"
RENDER_GOLDEN="$OUT_DIR/$CASE.render.golden.txt"
RENDER_STDERR="$OUT_DIR/$CASE.render.stderr.golden.txt"
TICK_GOLDEN="$OUT_DIR/$CASE.tick.golden.txt"
STATE_GOLDEN="$OUT_DIR/state/$CASE.json"

mkdir -p "$OUT_DIR/state"

# The reference exits 10 on a change and 0 on no change; both are success. Disable
# `set -e` around the calls so those exits can be inspected.
set +e
SWEEP_GATE_STATE_DIR="$BASE/render-state" \
    python3 "$REFERENCE" --topic "$SUBJECT" --vault "$VAULT" --render \
    > "$BASE/render.out" 2> "$BASE/render.err"
RENDER_EXIT=$?
set -e
if [ "$RENDER_EXIT" -ne 10 ] && [ "$RENDER_EXIT" -ne 0 ]; then
    echo "render exited $RENDER_EXIT" >&2
    cat "$BASE/render.err" >&2
    exit 1
fi

{ printf '%s\n' "$MARKER"; cat "$BASE/render.out"; } > "$RENDER_GOLDEN"
cp "$BASE/render.err" "$RENDER_STDERR"

# --- tick -------------------------------------------------------------------
set +e
SWEEP_GATE_STATE_DIR="$BASE/tick-state" \
    python3 "$REFERENCE" --topic "$SUBJECT" --vault "$VAULT" --tick \
    > "$BASE/tick.out" 2> "$BASE/tick.err"
TICK_EXIT=$?
set -e
if [ "$TICK_EXIT" -ne 10 ] && [ "$TICK_EXIT" -ne 0 ]; then
    echo "tick exited $TICK_EXIT" >&2
    cat "$BASE/tick.err" >&2
    exit 1
fi

{ printf '%s\n' "$MARKER"; cat "$BASE/tick.out"; } > "$TICK_GOLDEN"

# The state file is named by the SUBJECT slug, not the case name.
STATE_SLUG=$(printf '%s' "$SUBJECT" | tr '[:upper:]' '[:lower:]' \
    | sed -E 's/[^a-z0-9]+/-/g; s/^-+//; s/-+$//')
cp "$BASE/tick-state/$STATE_SLUG.json" "$STATE_GOLDEN"

# --- verify -----------------------------------------------------------------
for produced in "$RENDER_GOLDEN" "$RENDER_STDERR" "$TICK_GOLDEN" "$STATE_GOLDEN"; do
    if [ ! -s "$produced" ]; then
        echo "missing or empty golden: $produced" >&2
        exit 1
    fi
done

echo "wrote $RENDER_GOLDEN"
echo "wrote $RENDER_STDERR"
echo "wrote $TICK_GOLDEN"
echo "wrote $STATE_GOLDEN"
